function downloadBaseSlug(segment) {
  return String(segment || "datasheets").replace(/-\d+$/, "");
}

function productIdFromPath(path) {
  return routePathOnly(path).split("/").filter(Boolean).pop();
}

function renderDownloadPage(segment, params = new URLSearchParams(), currentPath = "") {
  const slug = downloadBaseSlug(segment);
  const page = pageFor(currentPath || `/download/${segment}`);
  const active = downloadCategories().find((item) => item[0] === slug) || downloadCategories()[0];
  const selectedProduct = params.get("product");
  const productPool = cmsPages().filter((item) => /^\/products\/[^/]+\/[^/]+$/.test(routePathOnly(item.path)));
  const relatedProducts = (selectedProduct
    ? productPool.filter((item) => productIdFromPath(item.path) === selectedProduct)
    : productPool
  ).slice(0, selectedProduct ? 1 : 12);
  const selectedLabel = selectedProduct && relatedProducts[0] ? cleanTitle(relatedProducts[0].title) : "";
  return `${renderHeader()}<main class="inside-main">
    ${sourceBannerHero("DOWNLOADS", `${ASSET}/download-hero.jpg`, ["Home", "Downloads", active[1]])}
    <section class="category-tabs download-tabs">${downloadCategories().map(([key, label]) => `<a class="${key === slug ? "active" : ""}" href="${localHref(`/download/${key}`)}">${esc(label)}</a>`).join("")}</section>
    <section class="download-list">
      <div class="download-filter"><h2>${esc(active[1])}${selectedLabel ? `<small>${esc(selectedLabel)}</small>` : ""}</h2><a class="filter-pill" href="${localHref(`/download/${slug}`)}">${icon("search")} ${selectedLabel ? "All Products" : "All Products"}</a></div>
      <div class="download-card-grid">
        ${relatedProducts.map((product, index) => `<a class="download-card" href="${localHref(`/download/${slug}?product=${productIdFromPath(product.path)}`)}">
          <b>${esc(active[1])}</b><h3>${cleanTitle(product.title)} ${esc(active[1])}</h3><p>PDF / Version ${index + 1}.0 / CMS downloadable asset</p>${icon("arrow")}
        </a>`).join("")}
      </div>
      ${renderDownloadPagination(slug, segment)}
    </section>
    ${renderFooterCta()}
  </main>${renderFooter()}`;
}

function renderDownloadPagination(slug, segment) {
  const pageNumber = Number(String(segment || "").match(/-(\d+)$/)?.[1] || 1);
  const maxBySlug = slug === "certificates" ? 4 : (slug === "datasheets" || slug === "user-manual" ? 3 : (slug === "quick-install-guides" ? 2 : 1));
  if (maxBySlug <= 1) return "";
  return `<nav class="page-dots">${Array.from({ length: maxBySlug }).map((_, i) => {
    const page = i + 1;
    const target = page === 1 ? `/download/${slug}` : `/download/${slug}-${page}`;
    return `<a class="${page === pageNumber ? "active" : ""}" href="${localHref(target)}">${page}</a>`;
  }).join("")}</nav>`;
}

